$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Windows.Forms,System.Drawing
Add-Type @"
using System;using System.Runtime.InteropServices;public static class MenuNative{
[DllImport("user32.dll")]public static extern bool GetLayeredWindowAttributes(IntPtr h,out uint key,out byte alpha,out uint flags);
[DllImport("user32.dll")]public static extern IntPtr SendMessage(IntPtr h,int m,IntPtr w,IntPtr l);
}
"@
[Windows.Forms.Application]::EnableVisualStyles();$a=[Reflection.Assembly]::LoadFrom((Join-Path $PWD 'DeepSeekBalance\build\DeepSeekBalance.exe'));$t=$a.GetType('DeepSeekBalance.Bar');$f=[Reflection.BindingFlags]'Instance,NonPublic';$b=[Activator]::CreateInstance($t);$t.GetField('busy',$f).SetValue($b,$true);foreach($field in @('refresh','position')){$t.GetField($field,$f).GetValue($b).Stop()};$handle=$b.Handle;$menu=$b.ContextMenuStrip
function Pump([int]$ms){$s=[Diagnostics.Stopwatch]::StartNew();while($s.ElapsedMilliseconds -lt $ms){[Windows.Forms.Application]::DoEvents();Start-Sleep -Milliseconds 8}}
function Check($name,$ok){if(-not $ok){throw $name};'PASS: '+$name}
try{
 Check 'About menu is only named About' (@($menu.Items|Where-Object{$_.Text -eq '关于'}).Count -eq 1 -and @($menu.Items|Where-Object{$_.Text -like '关于 *'}).Count -eq 0)
 $menu.Show([Drawing.Point]::new(400,400));Pump 100;Check 'Menu-only opening starts external click detector' $t.GetField('outsideClicks',$f).GetValue($b).Enabled
 $pointType=$t.GetNestedType('NativePoint',[Reflection.BindingFlags]'NonPublic');$inside=[Activator]::CreateInstance($pointType,[object[]]@([int]($menu.Left+50),[int]($menu.Top+25)));$t.GetMethod('DismissOutside',$f).Invoke($b,[object[]]@($inside))|Out-Null;Check 'Inside menu is not dismissed by outside handler' $menu.Visible
 $outside=[Activator]::CreateInstance($pointType,[object[]]@(100,100));$t.GetMethod('DismissOutside',$f).Invoke($b,[object[]]@($outside))|Out-Null;Pump 50;Check 'External click closes menu without opening a detail panel' (-not $menu.Visible -and $null -eq $t.GetField('details',$f).GetValue($b))
 $menu.Show([Drawing.Point]::new(400,400));Pump 50;[void][MenuNative]::SendMessage($handle,0x202,[IntPtr]::Zero,[IntPtr](30+30*65536));Pump 100;Check 'Ring click closes menu instead of reopening details' (-not $menu.Visible -and $null -eq $t.GetField('details',$f).GetValue($b))
 $mt=$menu.GetType();$appearanceType=$a.GetType('DeepSeekBalance.PanelAppearance');$model=$appearanceType.GetMethod('Load',[type[]]@([string])).Invoke($null,[object[]]@([string](Join-Path $PWD 'DeepSeekBalance\build\menu-unused-settings.json')))
 foreach($light in @($false,$true)){foreach($opacity in @(0,60,99,100)){$menu.Show([Drawing.Point]::new(400,400));$appearanceType.GetField('Light').SetValue($model,$light);$appearanceType.GetField('Transparency').SetValue($model,[double]$opacity);$mt.GetMethod('ApplyAppearance').Invoke($menu,[object[]]@($model))|Out-Null;Pump 60;$bg=$mt.GetField('backdrop',$f).GetValue($menu);[uint32]$key=0;[byte]$alpha=0;[uint32]$flags=0;[void][MenuNative]::GetLayeredWindowAttributes($bg.Handle,[ref]$key,[ref]$alpha,[ref]$flags);$expected=$appearanceType.GetProperty('BackgroundAlpha').GetValue($model,$null);Check ('Background matches panel settings: light='+$light+' transparency='+$opacity) ($alpha -eq $expected -and ($flags-band 2)-ne 0 -and ($expected -ne 0 -or -not $bg.Visible));[void][MenuNative]::GetLayeredWindowAttributes($menu.Handle,[ref]$key,[ref]$alpha,[ref]$flags);Check 'Menu foreground remains color-keyed rather than faded' (($flags-band 1)-ne 0 -and ($flags-band 2)-eq 0);$menu.Close();Pump 30;Check 'Closing hides the menu material' (-not $bg.Visible)}}
 $script:clicked=0;$item=[Windows.Forms.ToolStripMenuItem]::new('菜单操作测试');$item.add_Click({$script:clicked++});[void]$menu.Items.Add($item);$menu.Show([Drawing.Point]::new(400,400));Pump 50;$point=$menu.PointToScreen([Drawing.Point]::new(($item.Bounds.Left+20),($item.Bounds.Top+10)));$mt.GetMethod('ClickBackground',$f).Invoke($menu,[object[]]@($point))|Out-Null;Pump 40;Check 'Clicking material inside a row runs item once and closes menu' ($script:clicked -eq 1 -and -not $menu.Visible)
}finally{$menu.Dispose();foreach($field in @('refresh','position','outsideClicks')){$t.GetField($field,$f).GetValue($b).Dispose()};$b.Dispose()}